create extension if not exists pgcrypto;
create table if not exists public.shipments (id uuid primary key default gen_random_uuid(),tracking_number text unique not null,recipient_name text,recipient_email text,origin text,destination text,service text,weight text,status text not null default 'processing' check (status in ('processing','in_transit','at_hub','out_for_delivery','delivered','exception')),estimated_delivery date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.shipments add column if not exists sender_name text;alter table public.shipments add column if not exists sender_phone text;alter table public.shipments add column if not exists package_description text;alter table public.shipments add column if not exists package_type text;alter table public.shipments add column if not exists pieces integer default 1;alter table public.shipments add column if not exists dimensions text;alter table public.shipments add column if not exists declared_value numeric;alter table public.shipments add column if not exists currency text;alter table public.shipments add column if not exists transport_mode text;
create index if not exists shipments_recipient_email_idx on public.shipments(recipient_email);
create table if not exists public.tracking_events (id uuid primary key default gen_random_uuid(),shipment_id uuid not null references public.shipments(id) on delete cascade,status text not null check (status in ('processing','in_transit','at_hub','out_for_delivery','delivered','exception')),location text,description text,event_time timestamptz not null default now(),created_by uuid references auth.users(id));
create index if not exists tracking_events_shipment_idx on public.tracking_events(shipment_id,event_time desc);
alter table public.shipments enable row level security;alter table public.tracking_events enable row level security;
drop policy if exists "admins can manage shipments" on public.shipments;drop policy if exists "admins can manage events" on public.tracking_events;
create policy "admins can manage shipments" on public.shipments for all to authenticated using ((auth.jwt()->'app_metadata'->>'role')='admin') with check ((auth.jwt()->'app_metadata'->>'role')='admin');
create policy "admins can manage events" on public.tracking_events for all to authenticated using ((auth.jwt()->'app_metadata'->>'role')='admin') with check ((auth.jwt()->'app_metadata'->>'role')='admin');
drop function if exists public.track_shipment(text);create or replace function public.track_shipment(p_tracking_number text) returns table(id uuid,tracking_number text,sender_name text,sender_phone text,recipient_name text,recipient_email text,origin text,destination text,service text,weight text,package_description text,package_type text,pieces integer,dimensions text,declared_value numeric,currency text,transport_mode text,status text,estimated_delivery date) language sql security definer set search_path=public as $$ select s.id,s.tracking_number,s.sender_name,s.sender_phone,s.recipient_name,s.recipient_email,s.origin,s.destination,s.service,s.weight,s.package_description,s.package_type,s.pieces,s.dimensions,s.declared_value,s.currency,s.transport_mode,s.status,s.estimated_delivery from public.shipments s where upper(s.tracking_number)=upper(p_tracking_number) limit 1 $$;
create or replace function public.track_events(p_tracking_number text) returns table(id uuid,shipment_id uuid,status text,location text,description text,event_time timestamptz) language sql security definer set search_path=public as $$ select e.id,e.shipment_id,e.status,e.location,e.description,e.event_time from public.tracking_events e join public.shipments s on s.id=e.shipment_id where upper(s.tracking_number)=upper(p_tracking_number) order by e.event_time desc $$;
revoke all on function public.track_shipment(text) from public;grant execute on function public.track_shipment(text) to anon,authenticated;
revoke all on function public.track_events(text) from public;grant execute on function public.track_events(text) to anon,authenticated;
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now();return new;end; $$;
drop trigger if exists shipments_updated_at on public.shipments;create trigger shipments_updated_at before update on public.shipments for each row execute function public.set_updated_at();
-- Create an Auth user in Supabase, then mark only that user as admin: update auth.users set raw_app_meta_data=coalesce(raw_app_meta_data,'{}'::jsonb)||'{"role":"admin"}'::jsonb where email='YOUR_ADMIN_EMAIL';